'use strict';

/**
* Test whether at least one element in a double-precision complex floating-point strided array is truthy.
*
* @module @stdlib/blas-ext-base-zany
*
* @example
* import Complex128Array from '@stdlib/array-complex128';
* import zany from '@stdlib/blas-ext-base-zany';
*
* var x = new Complex128Array( [ 0.0, 0.0, 1.0, 2.0 ] );
*
* var v = zany( x.length, x, 1 );
* // returns true
*
* @example
* import Complex128Array from '@stdlib/array-complex128';
* import zany from '@stdlib/blas-ext-base-zany';
*
* var x = new Complex128Array( [ 0.0, 0.0, 1.0, 2.0 ] );
*
* var v = zany.ndarray( x.length, x, 1, 0 );
* // returns true
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils-try-require';
import isError from '@stdlib/assert-is-error';
import main from './main.js';


// MAIN //

var zany;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	zany = main;
} else {
	zany = tmp;
}


// EXPORTS //

export default zany;

// exports: { "ndarray": "zany.ndarray" }
